import "C"

const MAX_PATH_LEN = 256

type FileRequest struct {
	Path     string `json:"path"`
	Category string `json:"category"`
}

func sanitizePath(input string) string {
	// Basic sanitization - remove null bytes
	cleaned := strings.ReplaceAll(input, "\x00", "")
	// Resolve to absolute
	abs, err := filepath.Abs(cleaned)
	if err != nil {
		return ""
	}
	return abs
}

func processFilePath(userPath string) (string, error) {
	// Allocate fixed-size C buffer for path processing
	cBuf := C.malloc(C.ulong(MAX_PATH_LEN))
	defer C.free(cBuf)

	// Zero the buffer
	C.memset(cBuf, 0, C.ulong(MAX_PATH_LEN))

	// Convert Go string to C string
	cInput := C.CString(userPath)
	defer C.free(unsafe.Pointer(cInput))

	// BUG: unsafe_copy uses strcpy which doesn't check bounds
	// If userPath > MAX_PATH_LEN, this overflows the heap buffer
	C.unsafe_copy((*C.char)(cBuf), cInput, C.int(MAX_PATH_LEN))

	// Convert back to Go string
	result := C.GoString((*C.char)(cBuf))
	return result, nil
}

func handleFileRead(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	userPath := r.URL.Query().Get("path")
	if userPath == "" {
		http.Error(w, "Missing path parameter", http.StatusBadRequest)
		return
	}

	// Process through C layer (vulnerable to overflow)
	processed, err := processFilePath(userPath)
	if err != nil {
		http.Error(w, "Processing error", http.StatusInternalServerError)
		return
	}

	// Sanitize the processed path
	safePath := sanitizePath(processed)
	if safePath == "" {
		http.Error(w, "Invalid path", http.StatusBadRequest)
		return
	}

	// Check prefix (can be bypassed via overflow corruption)
	allowedBase := os.Getenv("ALLOWED_BASE_DIR")
	if allowedBase == "" {
		allowedBase = "/srv/data"
	}

	if !strings.HasPrefix(safePath, allowedBase) {
		http.Error(w, "Access denied: path outside allowed directory", http.StatusForbidden)
		return
	}

	// Read and return file
	data, err := ioutil.ReadFile(safePath)
	if err != nil {
		http.Error(w, fmt.Sprintf("Cannot read file: %v", err), http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Write(data)
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	http.HandleFunc("/api/v1/files", handleFileRead)
	http.HandleFunc("/health", handleHealth)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	fmt.Printf("Starting file service on :%s\n", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
